import csv
import io
import re
from typing import List, Dict, Any


def parse_csv(raw_csv: str) -> Dict[str, Any]:
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for row in reader:
        if not row or not any(cell.strip() for cell in row):
            continue
        records.append(row)

    if not records:
        return {"columns": [], "rows": []}

    # Skip simple preamble lines, such as a title occupying a single cell.
    header_index = 0
    for i, row in enumerate(records):
        if sum(bool(cell.strip()) for cell in row) > 1:
            header_index = i
            break

    header = records[header_index]
    if header:
        header[0] = header[0].lstrip("\ufeff")

    # A trailing delimiter in the header creates an unnamed, redundant column.
    while header and not header[-1].strip():
        header.pop()

    columns = []
    for i, name in enumerate(header):
        name = name.strip()
        columns.append(name if name else "Column {}".format(i + 1))

    width = len(columns)
    rows = []

    for record in records[header_index + 1:]:
        values = list(record)

        # Ignore surplus trailing delimiters, but retain any nonempty excess data.
        while len(values) > width and not values[-1].strip():
            values.pop()

        if len(values) > width:
            for i in range(width, len(values)):
                columns.append("Column {}".format(i + 1))
            width = len(columns)

        if len(values) < width:
            values.extend([""] * (width - len(values)))

        rows.append(values)

    return {"columns": columns, "rows": rows}
